<script setup lang="ts">
import { computed, defineAsyncComponent, onMounted, ref, watch } from 'vue';
import { placesApi, locationApi, domainError, dateLabel, type Place, type Circle, type MapConfig, type SearchResult, type LocationPermissions, type LocationObservation } from '../services/domains';
import type { Platform } from '../services/runtime';
import { useLocationPermissionRefresh } from '../composables/useLocationPermissionRefresh';
const PlaceMap = defineAsyncComponent(() => import('./PlaceMap.vue'));
const props = defineProps<{ platform: Platform }>(); const emit = defineEmits<{ dirty: [value: boolean] }>();
const places = ref<Place[]>([]); const busy = ref(false); const error = ref<string | null>(null); const notice = ref<string | null>(null); const loaded = ref(false);
const editing = ref(false); const target = ref<Place | null>(null); const name = ref(''); const type = ref<Place['type']>('property'); const parentId = ref<string | null>(null); const aliases = ref(''); const circles = ref<Circle[]>([]);
const mapConfig = ref<MapConfig>({ tileUrl: null, attribution: '', geocodingConfigured: false }); const query = ref(''); const searchResults = ref<SearchResult[]>([]); const searchBusy = ref(false);
const mapCenter = ref<{ latitude: number; longitude: number } | null>(null); const areaConfirmed = ref(false); const deleteTarget = ref<Place | null>(null); const permissions = ref<LocationPermissions | null>(null);
const mapAccuracyMeters = ref<number | null>(null);
useLocationPermissionRefresh(props.platform,permissions);
const typeLabels: Record<Place['type'], string> = { property: 'Propriedade', room: 'Cômodo', outdoor: 'Área externa', other: 'Outro lugar' };
watch(editing, value => emit('dirty', value)); watch(circles, () => { areaConfirmed.value = false; }, { deep: true });
const orderedPlaces = computed(() => {
  const result: { place: Place; depth: number }[] = []; const visited = new Set<string>();
  function add(parent: string | null, depth: number) { places.value.filter(place => place.parentId === parent).sort((a,b) => a.name.localeCompare(b.name)).forEach(place => { if (visited.has(place.id)) return; visited.add(place.id); result.push({ place, depth }); add(place.id, depth + 1); }); }
  add(null, 0); places.value.filter(place => !visited.has(place.id)).forEach(place => result.push({place, depth: 0})); return result;
});
const parentOptions = computed(() => {
  const excluded = new Set<string>(target.value ? [target.value.id] : []); let changed = true;
  while (changed) { changed = false; places.value.forEach(place => { if (place.parentId && excluded.has(place.parentId) && !excluded.has(place.id)) { excluded.add(place.id); changed = true; } }); }
  return orderedPlaces.value.filter(item => !excluded.has(item.place.id));
});
async function load() { const result = await placesApi<Place[] | { places: Place[] }>('list'); places.value = Array.isArray(result) ? result : result.places; loaded.value = true; }
async function operation(action: () => Promise<unknown>) { if (busy.value) return; busy.value = true; error.value = null; notice.value = null; try { await action(); } catch (failure) { error.value = domainError(failure, 'Não foi possível concluir. Confira a conexão e tente novamente.'); } finally { busy.value = false; } }
onMounted(() => { void operation(async () => { await load(); try { mapConfig.value = await placesApi<MapConfig>('config'); } catch { /* Existing places remain available without maps. */ } if (props.platform === 'android') { try { permissions.value = await locationApi<LocationPermissions>('permissions'); } catch { /* Optional native location. */ } } }); });
function open(place?: Place) { target.value = place ?? null; editing.value = true; name.value = place?.name ?? ''; type.value = place?.type ?? 'property'; parentId.value = place?.parentId ?? null; aliases.value = place?.aliases.join(', ') ?? ''; circles.value = place ? place.circles.map(circle => ({ ...circle })) : []; mapCenter.value = null; mapAccuracyMeters.value = null; areaConfirmed.value = false; query.value = ''; searchResults.value = []; error.value = null; }
async function save() {
  if (!name.value.trim()) return;
  if (circles.value.length && !areaConfirmed.value) { error.value = 'Confirme o ponto e a área escolhidos no mapa antes de salvar.'; return; }
  await operation(async () => { const payload = { name: name.value.trim(), type: type.value, parentId: parentId.value, aliases: [...new Set(aliases.value.split(',').map(alias => alias.trim()).filter(Boolean))], circles: circles.value, ...(target.value ? { expectedRevision: target.value.revision } : {}) }; await placesApi(target.value ? 'update' : 'create', payload, target.value?.id); editing.value = false; await load(); notice.value = target.value ? 'Lugar salvo. Se houver lembretes usando esta área, confira a sincronização no celular na seção Lembretes.' : 'Lugar salvo.'; });
}
async function search() {
  if (searchBusy.value || !query.value.trim()) return; searchBusy.value = true; error.value = null;
  try { const result = await placesApi<{ configured: boolean; results: SearchResult[] }>('search', { query: query.value.trim() }); searchResults.value = result.results; if (!result.configured) error.value = 'A busca de endereços precisa ser configurada no servidor.'; else if (!result.results.length) error.value = 'Nenhum resultado. Tente um endereço mais completo ou ajuste pelo mapa.'; }
  catch { error.value = 'A busca não está disponível agora. Os lugares salvos continuam preservados.'; }
  finally { searchBusy.value = false; }
}
function choosePoint(point: { latitude: number; longitude: number }) { mapCenter.value = point; if (!circles.value.length) circles.value = [{ id: crypto.randomUUID(), latitude: point.latitude, longitude: point.longitude, radiusMeters: 150 }]; searchResults.value = []; }
async function current() {
  await operation(async () => { const response = await locationApi<LocationObservation | { observation: LocationObservation } | {latest:LocationObservation|null;status?:string}>('current'); const point = 'observation' in response ? response.observation : 'latest' in response ? response.latest : response; if (!point || !Number.isFinite(point.latitude) || !Number.isFinite(point.longitude)) throw Error('Nenhuma posição recente disponível. Verifique o celular de localização e as permissões.'); choosePoint(point); mapAccuracyMeters.value = point.accuracyMeters; const ageSeconds = point.ageSeconds ?? Math.max(0,(Date.now()-new Date(point.capturedAt).getTime())/1000); const previous = ageSeconds > 120 || ('status' in response && ['pending','source_unreachable'].includes(response.status ?? '')); notice.value = `${previous ? `Última posição disponível, de ${Math.ceil(ageSeconds/60)} min atrás; a atualização atual não foi confirmada.` : `Posição capturada em ${dateLabel(point.capturedAt)}.`} Confira a área; a precisão informada (${Math.round(point.accuracyMeters)} m) é uma estimativa.${point.syncPending ? ' Envio ao servidor pendente.' : ''}`; });
}
async function permission() { await operation(async () => { await locationApi('requestPermission', { background: false, precise: true }); permissions.value = await locationApi<LocationPermissions>('permissions'); }); }
async function remove() { if (!deleteTarget.value) return; const item = deleteTarget.value; await operation(async () => { await placesApi('remove', { expectedRevision: item.revision }, item.id); deleteTarget.value = null; await load(); notice.value = 'Lugar removido.'; }); }
</script>
<template>
  <section aria-labelledby="places-title"><h2 id="places-title">Lugares</h2><p class="settings-muted">Organize propriedades, cômodos e áreas externas. Cômodos podem herdar a área da propriedade sem uma geofence própria.</p><p v-if="error" class="settings-error" role="alert">{{ error }}</p><p v-if="notice" class="settings-status" role="status">{{ notice }}</p>
    <div v-if="!editing" class="settings-actions"><button class="settings-primary" :disabled="busy" @click="open()">Novo lugar</button><button :disabled="busy" @click="operation(load)">{{ busy ? 'Atualizando…' : 'Atualizar' }}</button></div>
    <form v-if="editing" class="settings-card settings-form" @submit.prevent="save"><h3>{{ target ? 'Editar lugar' : 'Novo lugar' }}</h3><label>Nome<input v-model="name" maxlength="100" required autocomplete="off" placeholder="Nome que você usa para este lugar" /></label><div class="settings-grid"><label>Tipo<select v-model="type"><option v-for="(label,key) in typeLabels" :key="key" :value="key">{{ label }}</option></select></label><label>Faz parte de<select v-model="parentId"><option :value="null">Lugar independente</option><option v-for="item in parentOptions" :key="item.place.id" :value="item.place.id">{{ '— '.repeat(item.depth) }}{{ item.place.name }}</option></select></label></div><label>Apelidos pessoais, separados por vírgula<input v-model="aliases" placeholder="Ex.: casa" /><small>Um apelido pode se referir a mais de um lugar. A Aegis usará o contexto recente do celular selecionado e perguntará se houver dúvida.</small></label>
      <div v-if="type !== 'room' || circles.length"><h3>Referência no mapa</h3><p class="settings-muted">Escolher um ponto não o transforma automaticamente em sua residência.</p><div class="settings-actions"><button v-if="platform === 'android' && !permissions?.foreground" type="button" :disabled="busy" @click="permission">Permitir localização em uso</button><button type="button" :disabled="busy || (platform === 'android' && !permissions?.foreground)" @click="current">Usar localização atual do celular</button></div><small v-if="mapConfig.geocodingConfigured">A busca envia o endereço digitado ao provedor {{ mapConfig.geocoderProvider === 'photon' ? 'Photon/Komoot, com dados do OpenStreetMap' : mapConfig.geocoderProvider || 'configurado pelo operador' }}. Ela ocorre somente ao tocar em Buscar; não há busca automática enquanto você digita.</small><label>Buscar endereço<input v-model="query" :disabled="!mapConfig.geocodingConfigured || searchBusy" placeholder="Digite o endereço e toque em Buscar" @keydown.enter.prevent="search" /></label><div class="settings-actions"><button type="button" :disabled="!mapConfig.geocodingConfigured || searchBusy || !query.trim()" @click="search">{{ searchBusy ? 'Buscando…' : 'Buscar endereço' }}</button></div><small v-if="!mapConfig.geocodingConfigured">Busca por endereço não configurada. Você pode selecionar e ajustar o ponto pelo mapa.</small><ul v-if="searchResults.length" class="place-search-results"><li v-for="(result,index) in searchResults" :key="index"><button type="button" @click="choosePoint(result)">{{ result.name }}</button></li></ul><PlaceMap v-model="circles" :config="mapConfig" :center="mapCenter" :accuracy-meters="mapAccuracyMeters" /><label v-if="circles.length" class="area-confirm"><input v-model="areaConfirmed" type="checkbox" />Conferi o ponto e a área. A cobertura representa este lugar.</label></div><small v-else>Este cômodo herdará o contexto da propriedade escolhida. GPS não identifica em qual cômodo o celular está.</small>
      <div class="settings-actions"><button class="settings-primary" :disabled="busy" type="submit">{{ busy ? 'Salvando…' : 'Salvar lugar' }}</button><button type="button" :disabled="busy" @click="editing = false">Cancelar</button></div>
    </form>
    <p v-if="!loaded && busy" role="status">Carregando lugares…</p><div v-if="loaded && !places.length && !editing" class="settings-empty">Nenhum lugar cadastrado. Adicione um ponto e confirme a área; seus endereços não serão presumidos.</div>
    <article v-for="item in orderedPlaces" :key="item.place.id" class="settings-card" :class="{'place-card-child': item.depth > 0}"><div class="settings-card-header"><div><h3>{{ item.place.name }}</h3><small>{{ typeLabels[item.place.type] }}<span v-if="item.place.parentId"> · {{ places.find(place => place.id === item.place.parentId)?.name }}</span></small></div><span class="settings-badge">{{ item.place.circles.length ? `${item.place.circles.length} círculo${item.place.circles.length > 1 ? 's' : ''}` : item.place.parentId ? 'Área herdada' : 'Sem área' }}</span></div><p v-if="item.place.aliases.length" class="settings-muted">Apelidos: {{ item.place.aliases.join(', ') }}</p><div class="settings-actions"><button :disabled="busy || editing" @click="open(item.place)">Editar</button><button class="settings-danger" :disabled="busy || editing" @click="deleteTarget = item.place">Excluir</button></div><div v-if="deleteTarget?.id === item.place.id" class="settings-error" role="alertdialog" aria-label="Excluir lugar"><p>Excluir {{ item.place.name }}?</p><p>Lugares com filhos ou usados por regras ativas precisam ser reorganizados antes da exclusão.</p><div class="settings-actions"><button class="settings-danger" :disabled="busy" @click="remove">Excluir lugar</button><button :disabled="busy" @click="deleteTarget = null">Cancelar</button></div></div></article>
  </section>
</template>
<style scoped>.place-card-child { margin-left: 20px; }.area-confirm { display: flex; align-items: center; gap: 10px; margin-top: 16px; }.place-search-results { list-style: none; padding: 0; }.place-search-results li { margin-top: 8px; }.place-search-results button { width: 100%; text-align: left; }</style>
